from seven_outings_story_20261105 import *
from html import escape

chapter('芙宁娜','今天不坐贵宾席',
 'Furina (genshin impact), one adult woman, white hair with blue streaks and curled side locks, heterochromatic blue eyes, tilted small navy top hat, ornate navy tailcoat, white ruffled shirt and blue jewel ribbon, canonical costume.',
 ['把剧本留在家里','认出来，也没关系','一场只有两位观众的演出','谢幕以后再走一会儿'],[
 ('平视近景。枫丹街口，芙宁娜递来两张歌剧票，随后又若无其事地收回其中一张，像刚临时改了主意。','芙宁娜：不，今天换个节目。\n我：你不是已经准备了三天？','她把票仔细收进衣袋。','Furina at a Fontaine street corner holds two plain theater tickets then tucks one into her coat pocket, trying to look casually confident. My open gloved hand in foreground, bright afternoon canal setting.'),
 ('平视中景。她领我走过剧院大门，却没有进去，转身指向运河边的小游园，帽檐随着动作一晃。','芙宁娜：今天我们当普通游客。没有贵宾席，也不用提前鼓掌。','我：听起来，这才是她真正准备的节目。','Furina outside grand Fontaine theater points toward a modest canal-side fair, playful determined smile toward viewer, my hand holding folded map foreground, sunny blue-gold city.'),
 ('俯视特写。她把零钱分成两小堆：一堆买游园券，一堆留给蛋糕。我伸手把自己的零钱也添进去。','我：蛋糕预算可以增加。\n芙宁娜：很好，你已经掌握了旅行的重点。','', 'POV canal-side ticket booth counter, Furina gloved hands divide coins into two small piles, my gloved hand adds a few coins. Her pleased smile visible above, fair ribbons, no text.'),
 ('平视近景。摊前两只便宜的半面具摆在我们之间。她拿起一只比脸还夸张的鸟嘴面具，又悄悄放回。','芙宁娜：算了。戴这个，反而更显眼。\n我：你刚才已经吸引到我了。','她隔着面具瞪了我一眼。','Furina at a carnival mask stall lifts an absurd decorative bird mask near her face without wearing it, amused embarrassed expression, my hand holds a simple small half mask at foreground, eye contact clear.'),
 ('平视中景。排队买饮料时，旁边传来认出她的声音。她肩膀一紧，下意识摆出熟悉的站姿。','路人（画外）：是芙宁娜小姐吗？\n芙宁娜：咳，正是——','那一瞬，她又像站回了聚光灯里。','Furina waiting at a canal fair drink stall suddenly straightens posture, polite performance smile slightly tense, looks just past viewer toward an offscreen greeter. My gloved hand holds two drink tokens foreground, no crowd faces.'),
 ('近景。我举起两杯刚买好的饮料，把其中一杯递给她，并没有替她回答。她看见杯沿的小纸伞，停了半拍。','我：你的那杯，少冰。','她手指慢慢松开了衣摆。','Close first-person my gloved hand offers Furina a cold drink with tiny paper umbrella, her blue eyes soften and shoulders relax, Fontaine fair stall, intimate clear portrait, ordinary sunny outing.'),
 ('平视近景。她接过饮料，朝画面外点头，声音恢复到平常说话的音量。随后把另一杯推回我手里。','芙宁娜：今天和朋友出来玩。祝你们也玩得开心。','说完，她先一步拉我离开了队伍。','Furina holding one paper drink cup gives a small natural friendly wave to someone offscreen then looks toward viewer with relieved smile. My own cup foreground, canal promenade, no stage.'),
 ('平视中景。转过街角，她背靠栏杆长长呼气。我看着她，她先举杯碰了碰我的杯沿。','芙宁娜：刚才那句，不错吧？\n我：尤其是“朋友”那部分。\n芙宁娜：……不要挑台词。','', 'Furina leans on canal railing after leaving crowd, gently taps her paper drink cup against mine in foreground, bashful proud smile, blue water and cream stone buildings, casual close shot.'),
 ('俯视近景。一阵风卷来一只纸偶，落在我鞋边。远处小游园的纸偶戏棚歪了半边，纸板道具散在地上。','我：有个演员逃跑了。\n芙宁娜：还没谢幕就退场？这可不行。','她已经蹲了下来。','Downward first-person view, my gloved hand picks up a small paper puppet from cobblestones, Furina crouches opposite and reaches for a fallen cardboard backdrop, little paper-puppet booth at canal fair, breezy afternoon.'),
 ('平视低机位。我们帮忙把小戏台扶正。芙宁娜检查湿掉的台词纸，我用手压住不断翘起的纸板角。','摊主（画外）：台词全糊了，今天怕是演不成。\n芙宁娜：故事还在。只是不在纸上了。','', 'Low first-person crouched beside miniature cardboard puppet theater, my gloved hand steadies backdrop, Furina examines a blank damp paper sheet with thoughtful expression, scattered simple puppets, no readable text.'),
 ('手部近景。她把一只纸做的骑士交给我，自己拿起戴王冠的小鸟。我们的手藏在小戏台下沿。','我：我没有排练过。\n芙宁娜：你的角色只需要回答——“然后呢？”','', 'POV close-up our gloved hands holding two small flat paper puppets behind miniature cardboard theater, one knight held by me and one crowned bird held by Furina. Her encouraging face visible beyond, warm daylight.'),
 ('平视近景。小戏台上，王冠小鸟飞过纸山。透过道具的空隙，我看见芙宁娜正努力忍住笑。','芙宁娜：小鸟决定，把王冠借给一块石头。\n我：然后呢？\n芙宁娜：然后，它终于可以去买蛋糕了！','台下传来笑声。她也跟着笑了。','First-person behind a tiny cardboard puppet stage, crowned paper bird flies above painted cardboard hills in Furina hand, Furina smiling freely just beyond scenery. My paper knight in foreground. Offscreen audience, cheerful spontaneous play.'),
 ('平视中景。演出结束，她和我从小戏台后探出头。这里只画我推开幕布的手；她朝台下小小地鞠了一躬。','芙宁娜：本场演出，到此结束。\n我（低声）：现在可以去买蛋糕了。','她点头，比任何谢幕都干脆。','First-person hand pulling aside a tiny cloth curtain at puppet booth, Furina visible opposite makes a small playful bow then looks at viewer with a delighted smile. Golden fair lights begin to glow, no visible protagonist head.'),
 ('俯视近景。甜品店窗边，我们各自的蛋糕盘并排放着。她把刚才那只纸鸟靠在糖罐旁，王冠歪得很明显。','我：今天还是演了一场。\n芙宁娜：嗯。但这一场，是我自己想演的。','', 'POV cafe table with two slices of cream cake, my gloved hand holds fork, Furina opposite places a tiny crowned paper bird beside sugar bowl, calm contented face, Fontaine canal sunset through window.'),
 ('平视近景。我举起叉子准备评价。她抢先用自己的叉子轻轻敲了下盘沿，做出暂停的手势。','芙宁娜：等一下。今天不写剧评。\n我：那写什么？\n芙宁娜：写“很好吃”。','她终于放心地吃下第一口。','Furina across cafe table raises one finger in a playful stop gesture while holding dessert fork in other hand, relaxed smile and direct eye contact, strawberry cake between us, my fork foreground, soft evening.'),
 ('俯视收尾。回程的长椅上，我打开笔记本，她把小纸鸟夹进空白页。只留下王冠露在书页外。','芙宁娜：下次，还坐普通席。\n我：好。蛋糕预算照旧。','书合上时，小鸟终于不用一直站在台上。','First-person notebook open on canal bench, Furina gloved hand places a small crowned paper bird between blank pages, my hand holds book open, her blue sleeve and relaxed face at top edge, twilight canal.')])

chapter('玛薇卡','去落日追不上的地方',
 'Mavuika (genshin impact), one tall athletic adult woman, long flame-red hair with golden-orange ends, orange eyes, canonical black biker suit with red-gold flame ornaments, gloves, sunglasses on head. Friendly confident adventurer.',
 ['今日没有集合号','路线计划以外','先停下来再看远方','落日没有错过我们'],[
 ('平视中景。纳塔高地入口，玛薇卡靠在摩托旁等我。她指了指绑好的野餐袋，又拍了拍备用头盔。','玛薇卡：今天的补给很齐全。\n我：准备作战？\n玛薇卡：准备饿了就吃。','', 'Mavuika beside a black-gold fantasy motorcycle at Natlan plateau entrance, smiling toward viewer, picnic bag strapped securely to bike and spare black helmet on seat. My gloved hand holds a small travel notebook foreground, bright morning.'),
 ('近景。她把头盔递到我眼前，等我接稳后才放手。视野下沿出现我扣好护具的双手。','玛薇卡：先戴好。想看风景，也得平安到达。','她说得轻松，检查却一点不敷衍。','First-person Mavuika holds out a single spare black motorcycle helmet toward camera, friendly attentive face. My two gloved hands reach to receive it, motorcycle parked behind, no motion, warm natural light.'),
 ('俯视近景。地图被压在车座上，她指向一处看日落的高台。我在旁边画了一个小小的圆。','我：一定要赶到这里？\n玛薇卡：听说不错。先去看看。','“先去看看”，听上去比“必须到达”舒服。','POV looking down at a simple illustrated canyon map without labels spread on parked bike seat, Mavuika black glove points to a ridge, my gloved hand marks a blank circle with pencil, helmet beside map.'),
 ('第一人称骑行大景。镜头位于后座，只见我的手稳稳握住后座扶手，前方是她的肩背与头盔、延展的红色山路。','玛薇卡（前方）：准备好了？\n我：好了！','风把回答拖得很长。','Strict first-person passenger view from back seat of moving fantasy motorcycle at safe speed on broad empty Natlan road. Mavuika driver seen naturally from behind wearing black protective helmet, her red hair visible below it; my own gloved hands hold passenger grab rails at bottom, distant red cliffs. No external camera.'),
 ('平视中景。第一个休息点，她摘下头盔，把水壶递来。我的手还保持着刚才握扶手的动作，她忍不住笑。','玛薇卡：手可以放松了，我们已经停下了。\n我：身体知道，手还在赶路。','', 'Mavuika at a roadside overlook with motorcycle safely parked, helmet resting on seat, offers a metal water flask toward viewer with warm amused smile. My gloved hand half curled in foreground, red canyon view.'),
 ('平视大景。前方山路被落石挡住，路障旁挂着临时封路牌。她沿障碍看了一眼，回到我身边。','我：能绕过去吗？\n玛薇卡：能。但不用从这里冒险。','她把车钥匙收进口袋，没有尝试冲过去。','Mavuika stands beside parked motorcycle before a clearly blocked mountain road with fallen rocks and plain barricade, turns toward viewer decisively but calmly. My map in foreground, safe distance from obstruction, cloudy Natlan cliffs.'),
 ('俯视近景。地图重新摊开。我指向一条更长的步道，玛薇卡看了看天色，把野餐袋从车上卸下。','玛薇卡：换条路，走过去。\n我：可能赶不上原来的高台。\n玛薇卡：那就找一个新的。','', 'POV map on parked bike seat, my finger points to an alternate walking trail, Mavuika lifts a picnic satchel off bike rack, optimistic expression, helmets secured on parked motorcycle, Natlan hiking trail entrance.'),
 ('低角度近景。踏上石阶时，我的背包带挂住岩角。她停下来替我解开，没有催促。前方还有很长一段坡。','玛薇卡：别急。今天没人等我们打赢什么。','我的肩膀，在那句话后松了一点。','First-person close view of Mavuika facing viewer on a rocky hiking path, gently frees a loose backpack strap visible at bottom foreground from a rock edge. Patient encouraging smile, picnic bag over shoulder, late afternoon canyon.'),
 ('平视中景。我们在半坡遇上短雨，她招手带我躲进宽阔石拱下。袋子先被她放到最干燥的地方。','我：最重要的补给保住了。\n玛薇卡：很好，我们已经取得阶段性胜利。','', 'Mavuika beneath a broad natural stone arch during a brief rain shower places picnic bag on a dry rock, looks toward first-person camera with joking victorious smile. My gloved hand catches a raindrop outside shelter, Natlan canyon.'),
 ('俯视近景。我铺开野餐布，她把食物一份份摆好。景色暂时只剩石壁，热食的香气却让地方立刻像个目的地。','我：现在就吃？\n玛薇卡：肚子不会等日落批准。','', 'POV picnic under dry stone arch, my gloved hands spread cloth on flat rock, Mavuika opposite unpacks simple bread and grilled food into small boxes, rain outside, cozy adventurous mood, no fire hazard.'),
 ('平视近景。她捧着水杯看雨，难得没有主动接话。我咬下一口面包，也没有急着找话题。','我：你平时会这样坐一会儿吗？\n玛薇卡：比我应该做到的，少一些。','她说完，自己也想了想。','Mavuika seated relaxed under rock shelter cradles a metal cup, gazes at rain with reflective gentle face, my hand holding bread foreground, rain-softened red canyon, quiet medium portrait.'),
 ('近景。她转过头，眼底又有了笑意，却不再像出发时那样催着时间往前。','玛薇卡：所以今天，记得提醒我。\n我：提醒什么？\n玛薇卡：休息够了再走。','我把剩下的面包递过去，作为回答。','Mavuika turns toward camera with soft honest smile while seated beside picnic, my gloved hand offers a piece of bread. Wet red rocks beyond shelter, calm light, clear expressive face, no combat.'),
 ('仰视大景。雨渐渐停了，石拱另一端透进一道金光。我放下杯子，指给她看；她顺着我的手转身。','我：那边。\n玛薇卡：……看来有新路线了。','', 'First-person under natural stone arch, my gloved index finger points toward a shaft of golden sunset light at far opening. Mavuika stands and looks toward it with delighted surprise, rain clearing over canyon.'),
 ('主观大景。走出石拱，整片峡谷被晚霞点亮，浅水洼里映出第二个太阳。我的手扶着石边，玛薇卡站在画面侧前方。','玛薇卡：没有到高台，也能看见。','原来我们绕开的，是原定的路线，不是今天。','Wide first-person view emerging from stone arch into immense Natlan canyon at sunset, golden sun reflected in shallow puddles. My gloved hand rests on rock in foreground, Mavuika at side foreground turns to camera smiling, landscape dominant.'),
 ('平视近景。她抬起拳头，我轻轻碰上去。两个手套间是最后一束夕光，谁也没有马上把手放下。','我：今天算完成计划了吗？\n玛薇卡：超额完成。吃饱，看见落日，还学会了停一下。','', 'First-person fist bump with Mavuika at canyon sunset, my black-gold gloved fist touches her black biker glove in foreground, her delighted face behind hands, flame-red hair backlit, warm shared accomplishment.'),
 ('俯视收尾。返程前，我在笔记本里夹入野餐袋上的红色布签。玛薇卡的手把头盔重新递到画面里。','玛薇卡：回程慢一点？\n我：慢一点。','这次，不需要追着任何东西走。','POV notebook held above parked motorcycle seat at twilight, red fabric picnic tag laid on blank page, Mavuika hands offer black protective helmet at upper foreground, her patient smile in background, safe parked scene.')])

chapter('冰之女皇','雪落在谁的肩上',
 'Exactly one mature regal adult woman, original fan interpretation of an ice queen. Single female subject. Long straight silver-white hair, pale blue eyes, modest dark navy high-collared winter dress, white fur-lined blue cloak with silver frost embroidery, simple silver snowflake brooch, no crown today. Reserved gentle expression. Not a duplicate or twins.',
 ['把称呼留在门口','没有人预先安排的快乐','一条断掉的冰船','今晚，雪只是雪'],[
 ('平视中景。至冬宫门旁，女皇摘下华贵头饰，换上简单的蓝色兜帽。她看着我，像在等待一份陌生的规则。','女皇：今日，需要我做什么？\n我：先走出这扇门。剩下的，到街上再决定。','本篇为同人假想出游，不承接官方身份或外交剧情。','One mature silver-haired ice queen in modest navy winter dress and white-fur blue cloak stands at palace side door, simple hood lowered, no crown, looks at viewer with reserved curiosity. My gloved hand holds door open, snowy morning, single woman.'),
 ('俯视近景。我递出一副普通的保暖手套。她低头看了片刻，仍把它接过去，一根手指一根手指地戴好。','女皇：你担心我怕冷？\n我：至少，拿热杯子的时候用得上。','她没有再拒绝。','First-person close-up my black-gloved hands offer a pair of plain blue wool mittens, single silver-haired adult ice queen opposite accepts them, subtle amused expression, winter palace doorway, modest fur cloak.'),
 ('平视大景。冬日集市的拱门前，叫卖声、铃声和脚步声混在一起。她停在入口，我伸手替她掸去肩上的雪。','我：人有一点多。\n女皇：无妨。只是……比远处听起来，要热闹。','', 'Single silver-haired adult queen in simple blue hooded fur cloak at snowy winter market entrance, my gloved hand brushes snow from her shoulder foreground. Curious pale blue eyes, warm stalls and distant indistinct silhouettes, no attendants or guards.'),
 ('近景。热饮摊递来两杯巧克力。我先接过，再递给她。她下意识端得十分端正，被杯沿的热气熏得眨了一下眼。','我：先吹一吹。\n女皇：我知道。','她说完，还是照做了。','Close first-person portrait of one silver-haired adult queen holding steaming hot chocolate in wool-mittened hands, gently blowing at steam, restrained slightly embarrassed smile. My own cup foreground, warm winter fair stall, snow.'),
 ('平视中景。集市中央有人在比赛推小冰船。她看完规则，把空杯收好，转头问我是否愿意一起试试。','女皇：不借助力量，只推一次？\n我：对。谁离铃铛近，谁赢。','', 'Single adult silver-haired queen at a small winter fair tabletop ice-boat game, looks toward camera with quiet competitive curiosity, small carved ice boats and a brass bell on low icy lane, my hand holds an entry token foreground.'),
 ('俯视动作格。我先推了一下，冰船撞上边沿，转着圈停在半路。她抿了抿嘴，没能完全藏住笑意。','我：路面比想象中滑。\n女皇：这似乎不是路面的问题。','原来她也会这样接话。','POV over miniature ice-boat game table, my gloved fingers just released a small transparent ice boat now tilted near side bumper. Single silver-haired queen opposite covers a tiny amused smile with mitten, winter fair lights.'),
 ('平视近景。她的船滑得笔直，眼看要碰铃铛，却先卡在一块凸起的小冰粒上。我们同时俯身看过去。','女皇：这里不平。\n我：想把它冻平吗？\n女皇：……规则并未允许。','', 'Single silver-haired queen leans over tiny ice-boat lane with concentrated almost comic frustration, one little ice boat stopped just short of brass bell by tiny ice bump. My gloved hand rests on edge, no magic, warm winter market.'),
 ('手部近景。我把那块冰粒拨到一边，向摊主重新买了一次机会。她轻轻碰住我的手腕，示意这次让我来。','女皇：你推，我看方向。\n我：这算双人参赛？\n女皇：刚刚问过，允许。','', 'First-person hands at winter game table, single queen blue mitten gently touches my wrist to guide direction, small clear ice boat between our hands, her thoughtful encouraging face above, brass bell at far end.'),
 ('平视动作格。船终于碰响了铃，旁边却有另一只小船被袖口带落。女皇转身，破碎的冰片已经散在桌角。','我：先别动，我来捡。','她看着那只断掉的船，神情一点点安静下来。','Single silver-haired adult queen at winter stall looks down with concerned expression at a small broken decorative ice boat on table corner, my gloved hand reaches to collect pieces safely. Intact game boat by brass bell in background.'),
 ('近景。她抬起手，指尖凝出一点寒光。我托住船底，轻轻摇头，指向摊位旁的一盒绳线和木片。','我：先问问，有没有普通的修法。\n女皇：你不希望我修好它？\n我：希望。只是想一起试试。','', 'Close first-person my gloved palm holds base of tiny broken decorative ice boat, single silver-haired queen pauses with one mitten lifted and a very faint cool sparkle. A repair kit of twine and tiny wooden pieces sits nearby, calm eye contact, no attack.'),
 ('俯视近景。摊主给了一小片木板做底托。我扶住船身，她用绳线慢慢把裂开的两部分固定好。','女皇：这样，裂痕仍然看得见。\n我：嗯，但现在它可以被拿起来了。','', 'POV tabletop repair close-up, my gloved hands steady a small cracked decorative ice boat on a tiny wooden cradle, single queen mitten-free hands carefully tie twine around base. Her silver hair and focused face visible above, cozy fair lamplight.'),
 ('平视近景。她托起修好的船，光从裂痕里透过去，像一条不规则的河。她没有再把它变得完美。','女皇：它比原先，多了一副船架。\n我：也多了两位船工。','她低低笑了一声。','Single mature silver-haired queen holds a small repaired ice boat with visible crack on a wooden cradle, looking at viewer with a rare warm smile. My hand supports edge of cradle foreground, warm lights shine through translucent boat.'),
 ('平视大景。夜色落下，我们带着奖品走出集市。她在桥边停下，将船架放在积雪的栏杆上。远处第一簇烟花升空。','女皇：这也是你安排的？\n我：不是。\n女皇：……很好。','', 'Single silver-haired queen in blue fur cloak stands at snowy stone bridge beside winter fair at night, small repaired ice boat on railing, looks toward first-person camera pleasantly surprised, first distant golden firework in sky. My hand on railing foreground.'),
 ('仰视近景。烟花亮起时，雪落到她的睫毛与兜帽边。我伸手指向天空，她却先看了看落在我手套上的雪。','女皇：你手上，也有。\n我：一会儿就会化。\n女皇：我知道。','这一次，她没有让它留下。','Intimate first-person winter portrait of single adult silver-haired queen with a few snowflakes on lashes and hood, gently looks at snow on my raised black glove in foreground, distant fireworks illuminate face softly, peaceful night.'),
 ('平视中景。返回宫门时，她没有马上进去，而是把那枚比赛得来的普通木牌交到我手里。兜帽上还留着薄雪。','女皇：下次，仍由你选路。\n我：有一条路，我也没走过。\n女皇：那更好。','', 'Single silver-haired adult queen at quiet snowy palace side entrance at night offers a small plain wooden game token into my open gloved palm, gentle reserved smile, blue fur hood dusted with snow, warm door light.'),
 ('俯视终章。我在灯下摊开笔记本：绿尾带、包杯纸、紫线、叶片、纸鸟、红布签，以及刚放下的木牌。书页已不像出发时那样空。','我：原来，没去完成什么，也能带回这么多。','七次出游结束。下一页，我仍然留白。','Final first-person still life of open blank travel notebook on warm desk, my black-gold gloved hands at edges. Seven souvenirs neatly arranged: green ribbon, brown wrapping paper, purple string, pressed leaf, crowned paper bird, red cloth tag, plain wooden token. Empty next page, soft lamp, no writing.')])

def main():
 OUT.mkdir(parents=True,exist_ok=True)
 panels=[];texts=['《七日留白：旅行者与七神的七次出游》','28页长篇分镜剧本 / 七篇独立故事 / 每篇4页，每页4格 / 总112格','',
 '设定：原创轻日常同人合集，旅行者采用空的服饰手部特征。水之篇由芙宁娜出演，冰之女皇采用原创同人造型与假想关系。七篇不用于推断官方时间线。',
 '叙事规则：全程从旅行者双眼所见出发；允许前景手、膝、鞋，不出现旅行者的脸、完整身体或外部第三人称镜头。对话中的“我”属于旅行者；内心独白后期排版，不要求绘图模型生成文字。',
 '制作规则：每格8张独立种子候选；不代选，不自动把候选组成成品漫画。用户选定后，再进行连续性修正与最终气泡排版。',
 '视觉统一：清晰二维线稿、赛璐璐上色。旅行者黑色露指手套、金色腕饰；每篇角色与服装固定。人物与道具仍需选图后审核生成差异。','']
 page_sections=[]
 for ci,c in enumerate(CHAPTERS):
  texts+=['═'*36,f'第{ci+1}篇  {c["name"]}｜{c["title"]}','═'*36]
  for pi,pt in enumerate(c['page_titles']):
   pn=ci*4+pi+1; title=f'第{pn:02}页 · {pt}';texts+=['',title,'建议布局：4格，自左至右、由上至下；第4格作为翻页钩子或章节收束。','']
   cards=[]
   for k,row in enumerate(c['rows'][pi*4:pi*4+4],1):
    visual,dialogue,narration,prompt=row
    pid=f'P{pn:03}-K{k:02}'
    d=dict(id=pid,chapter=ci+1,character=c['name'],chapter_title=c['title'],page=pn,panel=k,page_title=pt,visual=visual,dialogue=dialogue,narration=narration,identity=c['identity'],scene_prompt=prompt,candidate_count=8)
    panels.append(d)
    texts.extend([pid+'｜'+visual,'对白：'+dialogue.replace('\n',' / '),'独白／旁白：'+(narration or '无。以停顿和动作承接。'),''])
    cards.append('<article><b>'+pid+'</b><p><strong>镜头与动作</strong> '+escape(visual)+'</p><p class="speech">'+escape(dialogue).replace('\n','<br>')+'</p><p class="inner">'+escape(narration or '（留出无声停顿）')+'</p></article>')
   page_sections.append(f'<section id="p{pn}"><small>第{ci+1}篇 / {escape(c["name"])} · {escape(c["title"])}</small><h2>{escape(title)}</h2>'+''.join(cards)+'</section>')
 spec=dict(title='七日留白：旅行者与七神的七次出游',pages=28,panels=112,candidates_per_panel=8,total_candidates=896,selection_policy='USER_ONLY',status='storyboard_ready',chapters=[{k:v for k,v in c.items() if k!='rows'} for c in CHAPTERS],storyboard=panels)
 (OUT/'storyboard.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2),encoding='utf-8')
 (OUT/'完整剧本与分镜.txt').write_text('\n'.join(texts),encoding='utf-8')
 nav=''.join(f'<a href="#p{i*4+1}">{escape(c["name"])}</a>' for i,c in enumerate(CHAPTERS))
 doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>七日留白 · 完整分镜剧本</title><style>body{margin:0;background:#eeeae2;color:#253140;font:17px/1.9 system-ui,"Microsoft YaHei",sans-serif}header,section,footer{max-width:880px;margin:28px auto;padding:32px 40px;background:#fffdf8;border-radius:12px}h1{line-height:1.4}h2{margin:10px 0 22px}small,.inner{color:#687379}nav{display:flex;flex-wrap:wrap;gap:18px}a{color:#8a5a2b}article{border-top:1px solid #ded9cf;padding:22px 0}article b{color:#997046}article p{margin:8px 0}.speech{padding:12px 20px;background:#f0f4f3;border-radius:8px}footer{font-size:14px}@media(max-width:600px){header,section,footer{padding:22px;margin:14px}}@media print{body{background:white}header{page-break-after:always}section{page-break-after:always;margin:0;padding:10mm;max-width:none;border-radius:0}article{break-inside:avoid}nav{display:none}}</style><header><h1>七日留白</h1><p>旅行者与七神的七次出游<br>28 页 · 112 格 · 每格 8 张候选，全部由你选</p><p>全程旅行者第一人称。每篇独立完成一次出游，包含出发、途中变化、共同解决的小事与告别。七件小纪念物串起整部作品。</p><p>原创同人假想合集：水之篇为芙宁娜，冰之女皇为原创同人造型。正文中的对白与独白在选图后排版。</p><nav>'''+nav+'</nav></header>'+''.join(page_sections)+'<footer>图片生成使用本地 DeltaMix v6。完整英文绘图描述、中文分镜及候选数量见同目录 storyboard.json；生成参数与种子见 workflows 目录。没有自动选图。</footer></html>'
 (OUT/'完整剧本与分镜.html').write_text(doc,encoding='utf-8')
 assert len(panels)==112 and len({p['page'] for p in panels})==28
 print(f'Prepared {len(CHAPTERS)} chapters, 28 pages, {len(panels)} panels, 896 candidates. Script length {len(chr(10).join(texts))} characters.')
if __name__=='__main__':main()
